<?php declare(strict_types=1);use PHPUnit\Framework\TestCase;final class SavedNumbersServiceTest extends TestCase {private function db():PDO{$db=new PDO('sqlite::memory:');$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$db->exec("CREATE TABLE saved_numbers(id INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT,email_hash TEXT,tool TEXT,inputs_json TEXT,version INTEGER,status TEXT,confirm_token_hash TEXT,delete_token_hash TEXT,consent_save_text TEXT,consent_news_text TEXT,consent_benchmark_text TEXT,consent_save_at TEXT,consent_news_at TEXT,consent_benchmark_at TEXT,source_page TEXT,created_at TEXT,confirmed_at TEXT,last_used_at TEXT,reminder_sent_at TEXT)");return $db;}public function testPendingConfirmWrongTokenAndDelete():void{$db=$this->db();$s=new SavedNumbersService($db);$tokens=$s->createPending('A@example.ca','mow-price',['onsite'=>30],true,false,'/tools/mow-price/');$row=$db->query('SELECT * FROM saved_numbers')->fetch(PDO::FETCH_ASSOC);$this->assertNotSame($tokens['confirm_token'],$row['confirm_token_hash']);$this->assertNull($s->confirm('wrong'));$done=$s->confirm($tokens['confirm_token']);$this->assertSame('confirmed',$done['status']);$this->assertTrue($s->delete($done['delete_token']));$this->assertSame(0,(int)$db->query('SELECT COUNT(*) FROM saved_numbers')->fetchColumn());}public function testPurgeRulesAndReminderOnce():void{$db=$this->db();$s=new SavedNumbersService($db);$db->exec("INSERT INTO saved_numbers(email,email_hash,tool,inputs_json,version,status,confirm_token_hash,delete_token_hash,consent_save_text,source_page,created_at,last_used_at) VALUES ('a@b.ca','x','mow-price','{}',1,'pending','a','b','save','/', '2024-01-01','2024-01-01'),('c@d.ca','y','mow-price','{}',1,'confirmed','c','d','save','/','2024-01-01','2025-01-10')");$r=$s->purge(new DateTimeImmutable('2026-01-01 00:00:00',new DateTimeZone('UTC')),function(){return true;});$this->assertSame(1,$r['pending_deleted']);$this->assertSame(0,$r['confirmed_deleted']);$this->assertSame(1,$r['reminders_sent']);$r=$s->purge(new DateTimeImmutable('2026-01-02 00:00:00',new DateTimeZone('UTC')),function(){return true;});$this->assertSame(0,$r['reminders_sent']);}}
